<?php
function spFeedback(string $action,array $p):string{
 $messages=['sa_plan_module_delete'=>'Attendance module, timetable, drafts and recorded attendance deleted. Staff can create the module again.','sa_plan_clear'=>'Recorded attendance deleted. The module and timetable remain available.','sa_plan_student'=>'Student details saved.','sa_plan_student_delete'=>'Student removed from the register. Existing attendance retained.','sa_plan_import'=>'Student register imported successfully.','sa_plan_period'=>'Period time saved.','sa_plan_rights'=>'Tutor permissions saved.','sa_plan_slot'=>'Timetable saved.','sa_plan_slot_delete'=>'Timetable slot deleted.','sa_plan_generate'=>'Attendance draft generated. Check absences before submitting.','sa_plan_draft_save'=>'Attendance draft saved.','sa_plan_submit'=>'Attendance submitted successfully.','sa_plan_draft_discard'=>'Unsubmitted attendance draft discarded.','sa_plan_session_edit'=>'Attendance correction saved.','sa_plan_session_delete'=>'Attendance session deleted.','sa_draft_create'=>'Module created. Add its timetable next.','sa_window_create'=>'Submission period created.','sa_window_edit'=>'Submission period updated.','sa_window_delete'=>'Submission period deleted. Existing attendance retained.','sa_window_toggle'=>'Submission period status updated.','sa_request_code'=>'If this is an active teaching email, a code will arrive shortly. Check your inbox and spam folder.','sa_verify_code'=>'Email verified for two hours.','sa_append'=>'Attendance added. Identical existing cells were not counted twice.'];return $messages[$action]??'Attendance changes saved.';
}
function spReturnPage(string $action,int $id,array $p):string{
 $tools=['sa_plan_student'=>'students','sa_plan_student_delete'=>'students','sa_plan_import'=>'students','sa_plan_period'=>'periods','sa_plan_rights'=>'rights'];if(isset($tools[$action]))return '?page=sa_portal&tools='.$tools[$action];
 return '?page='.(str_starts_with($action,'sa_window_')?'sa_manage':($id?(in_array($action,['sa_correct','sa_verify'],true)?'sa_review':'sa_record'):'sa_portal')).($id?'&id='.$id:'').(!empty($p['window_id'])?'&window_id='.(int)$p['window_id']:'').(in_array($action,['sa_plan_generate','sa_plan_draft_save'],true)?'#enter-attendance':'');
}
